={
  "contents": [{
    "parts": [{
      "text": "Du bist ein Content-Stratege für CanGo App Empire (Canberk Kivilcim, Deutschland).

Erstelle 5 konkrete Content-Ideen für:
Thema: {{ $json.topic || 'Digitale Automatisierung' }}
Säule: {{ $json.pillar || 'Bot-Empire' }}
Format: {{ $json.format || 'LinkedIn Post' }}

Gib NUR JSON zurück:
{"ideas": [{"title": "...", "hook": "...", "format": "...", "cta": "..."}]}"
    }]
  }],
  "generationConfig": { "temperature": 0.8, "maxOutputTokens": 600 }
}

parameters.jsCode:
const raw = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '{"ideas":[]}'; 
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch(e) {
  parsed = { ideas: [{ title: 'Parse-Fehler', hook: e.message, format: 'Error', cta: '' }] };
}
return [{ json: parsed }];
